#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
// 参数 nums 是严格递增数组；结果要返回从 0 开始的下标。
int search(int*nums,int numsSize,int target) {
    int l=0,r=numsSize-1;
    // 只检查仍可能包含目标的闭区间，每轮排除已比较的中点。
    while(l<=r) {
        int m=l+(r-l)/2;
        if(nums[m]==target)return m;
        if(nums[m]<target)l=m+1;
        else r=m-1;
    }
    // 候选耗尽表示目标不存在，统一返回 -1。
    return -1;
}
int main(void) {
    int n;
    scanf("%d",&n);
    int*a=malloc(n*sizeof(int));
    for(int i=0;i<n;i++)scanf("%d",&a[i]);
    int target;
    scanf("%d",&target);
    printf("%d\n",search(a,n,target));
    free(a);
    return 0;
}

