public class Main  {
    static class Fast  {
        private final byte[] b=new byte[65536];
        int p=0,n=0;
        int read()throws Exception {
            if(p>=n) {
                n=System.in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next()throws Exception {
            StringBuilder s=new StringBuilder();
            int c;
            do {
                c=read();
            }
            while(c<=32&&c>=0);
            while(c>32) {
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        int num()throws Exception {
            return Integer.parseInt(next());
        }
    }
