use std::collections::HashMap;
struct Solution;
impl Solution  {
    // 参数 nums 是严格递增数组；结果要返回从 0 开始的下标。
    pub fn search(nums:Vec<i32>,target:i32)->i32 {
        // 有序条件让一次比较排除半边；Rust 用标准库完成二分查找。
        match nums.binary_search(&target) {
            // 候选耗尽表示目标不存在，统一返回 -1。
            Ok(i)=>i as i32,Err(_)=>-1
        }
    }
}
fn main() {
    let mut s=String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut it=s.split_whitespace();
    let n:usize=it.next().unwrap().parse().unwrap();
    let a:Vec<i32>=(0..n).map(|_|it.next().unwrap().parse().unwrap()).collect();
    let target:i32=it.next().unwrap().parse().unwrap();
    println!("{}",Solution::search(a,target));
}

